L["Clone sources"] = "複製來源"
-- en: "Comparison history"
L["Comparison history"] = "比較歷史"
-- en: "Complete the effect settings before applying."
L["Complete the effect settings before applying."] = "套用前請先完成效果設定。"
-- en: "Credits"
