L["Policy, query-validation or identity/selector availability reason for a nil selector."] = "選擇器為 nil 時的政策、查詢驗證或身分/選擇器可用性原因。"
-- en: "Policy, query-validation or required observation availability reason for a nil quantity."
L["Policy, query-validation or required observation availability reason for a nil quantity."] = "數量為 nil 時的政策、查詢驗證或所需觀測的可用性原因。"
-- en: "Policy, query-validation or required observation availability reason for a nil record."
L["Policy, query-validation or required observation availability reason for a nil record."] = "記錄為 nil 時的政策、查詢驗證或所需觀測的可用性原因。"
-- en: "Policy, query-validation or required-observation availability reason for a nil ID."
L["Policy, query-validation or required-observation availability reason for a nil ID."] = "ID 為 nil 時的政策、查詢驗證或所需觀測的可用性原因。"
