L["Policy, query-validation or required-observation availability reason for a nil match."] = "比對結果為 nil 時的政策、查詢驗證或所需觀測的可用性原因。"
-- en: "Policy, slot-validation or required observation availability reason for a nil type."
L["Policy, slot-validation or required observation availability reason for a nil type."] = "類型為 nil 時的政策、欄位驗證或所需觀測的可用性原因。"
-- en: "Policy, slot-validation, capability or native-call availability reason for a nil record."
L["Policy, slot-validation, capability or native-call availability reason for a nil record."] = "記錄為 nil 時的政策、欄位驗證、功能或原生呼叫的可用性原因。"
-- en: "Policy, snapshot, identity or threat observation availability reason."
L["Policy, snapshot, identity or threat observation availability reason."] = "政策、快照、身分或威脅值觀測的可用性原因。"
-- en: "Policy, token-validation or availability reason for a nil identity result."
L["Policy, token-validation or availability reason for a nil identity result."] = "身分結果為 nil 時的政策、代碼驗證或可用性原因。"
-- en: "Policy, validation or availability reason for a nil health observation."
L["Policy, validation or availability reason for a nil health observation."] = "生命力觀測為 nil 時的政策、驗證或可用性原因。"
-- en: "Policy, validation or availability reason for a nil snapshot."
L["Policy, validation or availability reason for a nil snapshot."] = "快照為 nil 時的政策、驗證或可用性原因。"
-- en: "Policy, validation or observation availability reason."
L["Policy, validation or observation availability reason."] = "政策、驗證或觀測的可用性原因。"
-- en: "Policy, validation or required observation availability reason."
L["Policy, validation or required observation availability reason."] = "政策、驗證或所需觀測的可用性原因。"
-- en: "Positive integer glyph item ID stored by the condition; arrays, item-set keys and spell IDs are not item references."
L["Positive integer glyph item ID stored by the condition; arrays, item-set keys and spell IDs are not item references."] = "條件中儲存的正整數雕紋物品 ID；陣列、物品組鍵與法術 ID 不是物品參照。"
-- en: "Positive integer level, false for a known absent unit, or nil when unavailable."
L["Positive integer level, false for a known absent unit, or nil when unavailable."] = "正整數等級；已知單位不存在時為 false，無法使用時為 nil。"
-- en: "Positive integer spell ID, not a spell-book slot."
L["Positive integer spell ID, not a spell-book slot."] = "正整數法術 ID，而不是法術書欄位。"
-- en: "Positive item ID or native-recognized item name/link to classify."
L["Positive item ID or native-recognized item name/link to classify."] = "要分類的正數物品 ID，或原生可辨識的物品名稱/連結。"
