L["Predicate that validates the proposed spell value."] = "驗證擬議法術值的判斷函式。"
-- en: "Present GUID, false for known absence, or nil when unavailable."
L["Present GUID, false for known absence, or nil when unavailable."] = "存在時為 GUID；已知不存在時為 false，無法使用時為 nil。"
